fs.mkdirSync(path.join(root, 'blog'), { recursive: true });
fs.writeFileSync(path.join(root, 'blog', 'index.html'), blogIndex, 'utf8');

const listDirs = dir => fs.existsSync(dir) ? fs.readdirSync(dir, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name).sort() : [];
const weatherSlugs = listDirs(path.join(root, 'weather'));
const glossarySlugs = listDirs(path.join(root, 'glossary'));
const climateArchiveYearSlugs = listDirs(path.join(root, 'climate-archive')).filter(s => /^\d{4}$/.test(s));
const hayFeverSlugs = listDirs(path.join(root, 'hay-fever'));
const today = new Date().toISOString().slice(0, 10);
const postDateBySlug = Object.fromEntries(posts.map(p => [p.slug, p.dateModified || p.datePublished]));

const sitemapUrls = [
  { loc: 'https://www.weathertell.com/', lastmod: today, changefreq: 'daily', priority: '1.0' },
  ...weatherSlugs.map(slug => ({ loc: `https://www.weathertell.com/weather/${slug}/`, lastmod: today, changefreq: 'hourly', priority: '0.8' })),
  { loc: 'https://www.weathertell.com/locations/', lastmod: today, changefreq: 'weekly', priority: '0.7' },
  { loc: 'https://www.weathertell.com/sunrise-sunset/', lastmod: today, changefreq: 'weekly', priority: '0.7' },
  { loc: 'https://www.weathertell.com/7-day-forecast/', lastmod: today, changefreq: 'daily', priority: '0.8' },
  { loc: 'https://www.weathertell.com/14-day-forecast/', lastmod: today, changefreq: 'daily', priority: '0.8' },
  { loc: 'https://www.weathertell.com/glossary/', lastmod: today, changefreq: 'monthly', priority: '0.6' },
  ...glossarySlugs.map(slug => ({ loc: `https://www.weathertell.com/glossary/${slug}/`, lastmod: today, changefreq: 'monthly', priority: '0.5' })),
  { loc: 'https://www.weathertell.com/water-temperature/', lastmod: today, changefreq: 'daily', priority: '0.6' },
  { loc: 'https://www.weathertell.com/snow-depth/', lastmod: today, changefreq: 'daily', priority: '0.6' },
  { loc: 'https://www.weathertell.com/climate-archive/', lastmod: today, changefreq: 'monthly', priority: '0.6' },
  { loc: 'https://www.weathertell.com/climate-archive/records/', lastmod: today, changefreq: 'monthly', priority: '0.5' },
  { loc: 'https://www.weathertell.com/climate-archive/compare/', lastmod: today, changefreq: 'monthly', priority: '0.5' },
  ...climateArchiveYearSlugs.map(slug => ({ loc: `https://www.weathertell.com/climate-archive/${slug}/`, lastmod: today, changefreq: 'yearly', priority: '0.4' })),
  { loc: 'https://www.weathertell.com/hay-fever/', lastmod: today, changefreq: 'daily', priority: '0.6' },
  ...hayFeverSlugs.map(slug => ({ loc: `https://www.weathertell.com/hay-fever/${slug}/`, lastmod: today, changefreq: 'daily', priority: '0.5' })),
  { loc: 'https://www.weathertell.com/blog/', lastmod: today, changefreq: 'weekly', priority: '0.7' },
  ...posts.map(p => ({ loc: `https://www.weathertell.com/blog/${p.slug}/`, lastmod: postDateBySlug[p.slug], changefreq: 'monthly', priority: '0.6' })),
  { loc: `https://www.weathertell.com/authors/${author.slug}/`, lastmod: today, changefreq: 'monthly', priority: '0.4' }
];
const sitemapXml = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${sitemapUrls.map(u => `  <url><loc>${u.loc}</loc><lastmod>${u.lastmod}</lastmod><changefreq>${u.changefreq}</changefreq><priority>${u.priority}</priority></url>`).join('\n')}\n</urlset>\n`;
fs.writeFileSync(path.join(root, 'sitemap.xml'), sitemapXml, 'utf8');

// Posts with pinUntil (ISO date) stay first on the homepage until that date has passed.
const pinToday = new Date().toISOString().slice(0, 10);
const isPinned = post => Boolean(post.pinUntil && post.pinUntil >= pinToday);
const recentPosts = [...allPostsSorted].sort((a, b) => isPinned(b) - isPinned(a)).slice(0, 3);
const recentCards = recentPosts.map(post => `<a class="article-card" href="blog/${post.slug}/"><div class="article-meta"><span class="article-label">${post.category}</span><span class="article-date">${formatDate(post.datePublished)}</span></div><h2>${post.title}</h2><p>${post.description}</p><span class="read-more">Read the article <b>→</b></span></a>`).join('');
const homepagePath = path.join(root, 'index.html');
const homepageHtml = fs.readFileSync(homepagePath, 'utf8');
const recentPostsMarker = /<!-- RECENT_POSTS_START -->[\s\S]*?<!-- RECENT_POSTS_END -->/;
if (recentPostsMarker.test(homepageHtml)) {
  fs.writeFileSync(homepagePath, homepageHtml.replace(recentPostsMarker, `<!-- RECENT_POSTS_START -->${recentCards}<!-- RECENT_POSTS_END -->`), 'utf8');
}

console.log(`Generated ${posts.length} blog articles, 1 author page, the blog index, updated homepage with ${recentPosts.length} recent articles, and rebuilt sitemap.xml with ${sitemapUrls.length} URLs.${scheduledPosts.length ? ` (${scheduledPosts.length} scheduled: ${scheduledPosts.map(p => p.slug + ' on ' + p.datePublished).join(', ')})` : ''}`);
